好，边界一并收紧：每行按字节限长，支持 CRLF、空行和无换行尾行，非法 UTF-8 或 JSON 都会明确抛出。

```python
from __future__ import annotations

import json
from typing import Any


class JsonlStreamParser:
    def __init__(self, max_line_bytes: int = 1_048_576) -> None:
        if max_line_bytes <= 0:
            raise ValueError("max_line_bytes must be positive")
        self._max_line_bytes = max_line_bytes
        self._buffer = bytearray()
        self._line_number = 0
        self._closed = False

    def feed(self, chunk: bytes) -> list[Any]:
        if self._closed:
            raise RuntimeError("parser is already finalized")
        if not isinstance(chunk, bytes):
            raise TypeError("chunk must be bytes")

        values: list[Any] = []
        start = 0
        while True:
            newline = chunk.find(b"\n", start)
            if newline < 0:
                self._append(chunk[start:])
                break
            self._append(chunk[start:newline])
            value = self._finish_line()
            if value is not None:
                values.append(value)
            start = newline + 1
        return values

    def finalize(self) -> list[Any]:
        if self._closed:
            raise RuntimeError("parser is already finalized")
        self._closed = True
        if not self._buffer:
            return []
        value = self._finish_line()
        return [] if value is None else [value]

    def _append(self, part: bytes) -> None:
        if len(self._buffer) + len(part) > self._max_line_bytes:
            raise ValueError("JSONL line exceeds max_line_bytes")
        self._buffer.extend(part)

    def _finish_line(self) -> Any | None:
        self._line_number += 1
        raw = bytes(self._buffer)
        self._buffer.clear()
        if raw.endswith(b"\r"):
            raw = raw[:-1]
        if not raw.strip():
            return None
        try:
            return json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError(f"invalid JSONL at line {self._line_number}") from exc
